// MP4 estrutural sintético para testes; não é um vídeo reproduzível.
export function fixtureMP4(duration=265,audio=true,suffix=''){const box=(type,...parts)=>{const payload=Buffer.concat(parts),h=Buffer.alloc(8);h.writeUInt32BE(8+payload.length);h.write(type,4);return Buffer.concat([h,payload]);};const mvhd=Buffer.alloc(100);mvhd.writeUInt32BE(1000,12);mvhd.writeUInt32BE(duration*1000,16);const tkhd=Buffer.alloc(84);tkhd.writeUInt32BE(1080*65536,76);tkhd.writeUInt32BE(1920*65536,80);const handler=kind=>{const b=Buffer.alloc(24);b.write(kind,8);return box('trak',box('tkhd',tkhd),box('mdia',box('hdlr',b)));};return Buffer.concat([box('ftyp',Buffer.from('isom0000')),box('moov',box('mvhd',mvhd),handler('vide'),...(audio?[handler('soun')]:[])),box('mdat',Buffer.from(suffix||'sample'))]);}
